content.css:
.st{--st-max:1180px;font-family:var(--font-sans,Inter,ui-sans-serif,system-ui,sans-serif);color:var(--color-text,#1a1a1a);-webkit-font-smoothing:antialiased}
.st *,.st *::before,.st *::after{box-sizing:border-box}
.st-wrap{max-width:var(--st-max);margin:0 auto;padding:0 1.5rem}
.st-sec{padding:5.5rem 0}
.st-sec--tint{background:var(--color-surface,#fff)}
.st-sec--rule{border-top:1px solid var(--color-border,#e5e5e5)}
.st-eyebrow{display:inline-flex;align-items:center;gap:.5rem;font-size:.75rem;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:var(--color-brand,#e2603a);margin:0}
.st-eyebrow::before{content:"";width:1.75rem;height:1px;background:currentColor;opacity:.5}
.st-h1{font-family:var(--font-heading,inherit);font-size:clamp(2.6rem,6.2vw,4.6rem);line-height:1.02;letter-spacing:-.04em;font-weight:700;margin:1.25rem 0 0}
.st-h2{font-family:var(--font-heading,inherit);font-size:clamp(1.9rem,3.8vw,2.9rem);line-height:1.06;letter-spacing:-.035em;font-weight:700;margin:1rem 0 0}
.st-h3{font-family:var(--font-heading,inherit);font-size:1.125rem;line-height:1.3;letter-spacing:-.015em;font-weight:600;margin:0}
.st-faded{color:var(--color-muted,#8b8b8b)}
.st-lead{max-width:46rem;font-size:1.0625rem;line-height:1.75;color:var(--color-text-secondary,#525252);margin:1.25rem 0 0}
.st-head{max-width:46rem;margin-bottom:3rem}
.st-actions{display:flex;flex-wrap:wrap;gap:.75rem;margin-top:2rem}
.st-btn{display:inline-flex;align-items:center;gap:.5rem;font-size:.9375rem;font-weight:600;line-height:1;padding:.85rem 1.4rem;border-radius:calc(var(--radius,.75rem) * 1.2);border:1px solid var(--color-border,#e5e5e5);color:var(--color-text,#1a1a1a);background:var(--color-bg,#fff);text-decoration:none;transition:background 140ms ease,border-color 140ms ease,color 140ms ease,transform 140ms ease}
.st-btn:hover{border-color:var(--color-text,#1a1a1a);transform:translateY(-1px)}
.st-btn--primary{background:var(--color-brand,#e2603a);border-color:var(--color-brand,#e2603a);color:var(--color-on-brand,#fff)}
.st-btn--primary:hover{filter:brightness(1.06);border-color:var(--color-brand,#e2603a)}
.st-btn--ghost{background:transparent;border-color:transparent;padding-inline:.25rem;color:var(--color-brand,#e2603a)}
.st-btn--ghost:hover{border-color:transparent;text-decoration:underline;text-underline-offset:.25em}
.st-grid{display:grid;gap:1.25rem}
.st-grid--2{grid-template-columns:repeat(auto-fit,minmax(20rem,1fr))}
.st-grid--3{grid-template-columns:repeat(auto-fit,minmax(17rem,1fr))}
.st-grid--4{grid-template-columns:repeat(auto-fit,minmax(13.5rem,1fr))}
.st-card{position:relative;display:flex;flex-direction:column;gap:.75rem;padding:1.75rem;background:var(--color-surface,#fff);border:1px solid var(--color-border,#e5e5e5);border-radius:calc(var(--radius,.75rem) * 1.6);transition:border-color 160ms ease,transform 160ms ease,box-shadow 160ms ease}
.st-card:hover{border-color:color-mix(in srgb,var(--color-brand,#e2603a) 45%,var(--color-border,#e5e5e5));transform:translateY(-2px)}
.st-card p{margin:0;font-size:.9375rem;line-height:1.7;color:var(--color-text-secondary,#525252)}
.st-num{font-family:var(--font-mono,ui-monospace,monospace);font-size:.75rem;font-weight:600;letter-spacing:.1em;color:var(--color-brand,#e2603a)}
.st-tags{display:flex;flex-wrap:wrap;gap:.375rem;margin:0;padding:0;list-style:none}
.st-tags li{font-size:.75rem;font-weight:500;line-height:1;padding:.4rem .6rem;border-radius:999px;background:var(--color-bg-subtle,#f7f7f7);border:1px solid var(--color-border,#e5e5e5);color:var(--color-text-secondary,#525252)}
.st-list{margin:0;padding:0;list-style:none;display:grid;gap:.6rem}
.st-list li{position:relative;padding-inline-start:1.5rem;font-size:.9375rem;line-height:1.6;color:var(--color-text-secondary,#525252)}
.st-list li::before{content:"";position:absolute;inset-inline-start:0;top:.55em;width:.5rem;height:.5rem;border-radius:2px;background:var(--color-brand,#e2603a)}
.st-stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(9rem,1fr));gap:1.25rem;margin:0;padding:0}
.st-stat{display:flex;flex-direction:column;gap:.35rem;padding:1.5rem 0}
.st-stat dt{order:2;font-size:.8125rem;letter-spacing:.06em;text-transform:uppercase;color:var(--color-muted,#8b8b8b)}
.st-stat dd{order:1;margin:0;font-family:var(--font-heading,inherit);font-size:clamp(2rem,4vw,2.75rem);line-height:1;letter-spacing:-.035em;font-weight:700}
.st-prose{max-width:44rem}
.st-prose h2{font-family:var(--font-heading,inherit);font-size:1.375rem;letter-spacing:-.02em;margin:2.75rem 0 .75rem}
.st-prose h3{font-size:1.0625rem;margin:2rem 0 .5rem}
.st-prose p,.st-prose li{font-size:1rem;line-height:1.75;color:var(--color-text-secondary,#525252)}
.st-prose ul{padding-inline-start:1.25rem;display:grid;gap:.4rem}
.st-prose a{color:var(--color-brand,#e2603a)}
.st-faq{display:grid;gap:.75rem;max-width:48rem}
.st-faq details{border:1px solid var(--color-border,#e5e5e5);border-radius:calc(var(--radius,.75rem) * 1.3);background:var(--color-surface,#fff);overflow:hidden}
.st-faq summary{display:flex;align-items:center;justify-content:space-between;gap:1rem;cursor:pointer;padding:1.15rem 1.35rem;font-weight:600;font-size:1rem;list-style:none}
.st-faq summary::-webkit-details-marker{display:none}
.st-faq summary::after{content:"+";font-size:1.35rem;font-weight:400;line-height:1;color:var(--color-brand,#e2603a);transition:transform 160ms ease}
.st-faq details[open] summary::after{transform:rotate(45deg)}
.st-faq .st-faq-a{padding:0 1.35rem 1.25rem;margin:0;font-size:.9375rem;line-height:1.7;color:var(--color-text-secondary,#525252)}
.st-cta{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:2rem;padding:3.5rem;border-radius:calc(var(--radius,.75rem) * 2);background:var(--color-text,#1a1a1a);color:var(--color-bg,#fff)}
.st-cta h2{font-family:var(--font-heading,inherit);font-size:clamp(1.75rem,3.4vw,2.5rem);line-height:1.08;letter-spacing:-.035em;font-weight:700;margin:0;max-width:20ch}
.st-cta p{margin:.85rem 0 0;font-size:.9375rem;color:color-mix(in srgb,var(--color-bg,#fff) 65%,transparent)}
.st-cta .st-btn{background:var(--color-brand,#e2603a);border-color:var(--color-brand,#e2603a);color:var(--color-on-brand,#fff)}
@media (max-width:720px){.st-sec{padding:3.5rem 0}.st-cta{padding:2.25rem}.st-head{margin-bottom:2rem}}
@media (prefers-reduced-motion:reduce){.st-card,.st-btn{transition:none}.st-card:hover,.st-btn:hover{transform:none}}
.st-page-hero{padding:5rem 0 3.5rem}
.st-page-hero .st-h1{max-width:15ch}
.st-phases{display:grid;gap:4rem;padding-block:4rem}
.st-phase-head{display:flex;align-items:flex-start;gap:1.5rem;margin-bottom:2rem}
.st-phase-num{flex:none;display:grid;place-items:center;width:3rem;height:3rem;border-radius:50%;background:var(--color-brand,#e2603a);color:var(--color-on-brand,#fff);font-family:var(--font-mono,ui-monospace,monospace);font-size:.9375rem;font-weight:700}
.st-flow{list-style:none;margin:0;padding:0;display:grid;gap:0;border-inline-start:2px solid var(--color-border,#e5e5e5);margin-inline-start:1.5rem}
.st-flow-step{position:relative;padding:0 0 2.25rem 2.5rem}
.st-flow-step:last-child{padding-bottom:0}
.st-flow-step::before{content:"";position:absolute;inset-inline-start:-7px;top:.45rem;width:12px;height:12px;border-radius:50%;background:var(--color-bg,#fff);border:2px solid var(--color-brand,#e2603a)}
.st-flow-step--fork::before{border-radius:2px;transform:rotate(45deg)}
.st-flow-step p{margin:.5rem 0 0;font-size:.9375rem;line-height:1.75;color:var(--color-text-secondary,#525252);max-width:44rem}
.st-forks{list-style:none;margin:1rem 0 0;padding:0;display:grid;gap:.5rem;max-width:44rem}
.st-forks li{display:grid;grid-template-columns:8rem 1fr;gap:1rem;align-items:baseline;padding:.7rem .95rem;border:1px dashed var(--color-border,#e5e5e5);border-radius:calc(var(--radius,.75rem) * 1.2);background:var(--color-surface,#fff);font-size:.875rem;line-height:1.55;color:var(--color-text-secondary,#525252)}
.st-forks span{font-weight:600;font-size:.75rem;letter-spacing:.08em;text-transform:uppercase;color:var(--color-brand,#e2603a)}
@media (max-width:640px){.st-phase-head{gap:1rem}.st-flow{margin-inline-start:.5rem}.st-flow-step{padding-inline-start:1.75rem}.st-forks li{grid-template-columns:1fr;gap:.25rem}}
